-- Sunstone: talent plans, one talent rank per level from 10 to 60 (51 points).
-- GENERATED by tools/talent_plans/build.py from tools/talent_plans/specs.py: edit the specs, not this file.
--
-- Each class has a plan for every goal it can do (Solo, Leveling, Dungeons/Raids, Tanking, Healing, DPS);
-- each plan says which goals it serves. The player picks a goal on the Talents tab (saved per character).
-- The desktop helper can still send a custom plan through Inbox.lua.
--
-- Every plan was checked step by step against WoW Forever's talent trees: one rank per level, no rank
-- above the talent's maximum, each row's 5-points-per-tier gate met, every prerequisite taken first.
-- Sources and the reasoning for each plan are in tools/talent_plans/specs.py.

local _, NS = ...

-- The goals a player can pick, in the order the Talents tab shows them. A class only shows
-- the goals it has a plan for (a Mage has no Tanking or Healing button).
NS.GOALS = {
  { "solo", "Solo", "Playing alone, including soloing dungeons" },
  { "leveling", "Leveling", "Fastest way to 60" },
  { "dungeons", "Dungeons/Raids", "Group content in your class's main group role" },
  { "tank", "Tanking", "Holding enemies off the group" },
  { "heal", "Healing", "Keeping the group alive" },
  { "dps", "DPS", "Damage in groups and raids" },
}

-- { talent, how many ranks to take now, note } entries, turned into one rank per level from 10.
local function Seq(list)
  local steps, lvl, have = {}, 10, {}
  for _, e in ipairs(list) do
    for i = 1, e[2] do
      have[e[1]] = (have[e[1]] or 0) + 1
      steps[lvl] = { e[1], have[e[1]], i == 1 and e[3] or nil }
      lvl = lvl + 1
    end
  end
  return steps
end

